// Tiny DOM toolkit. Every piece of text goes through text nodes, so data coming
// from the server (codes, descriptions, names) can never be interpreted as HTML.
// innerHTML is deliberately unsupported; the only trusted markup (the QR code SVG
// generated by the server) goes through svgFromString(), which sanitises it.

import { codeNorm, matchesLoose, textNorm } from './normalize.js';

const SVG_NS = 'http://www.w3.org/2000/svg';
const COMBINING_MARKS = /[\u0300-\u036F]/g;
const NB_HYPHEN = /\u2011/g;
const ORDINALS = /[\u00AA\u00BA]/;

// Keys written as DOM properties instead of attributes.
const PROPERTIES = new Set([
  'value',
  'checked',
  'disabled',
  'selected',
  'hidden',
  'indeterminate',
  'multiple',
  'readOnly',
  'required',
  'tabIndex',
  'textContent',
  'htmlFor',
  'defaultValue',
]);

const FORBIDDEN = new Set(['innerHTML', 'outerHTML', 'html', 'srcdoc']);

/** Parses "div.card.is-open#main" into { tag, id, classes }. */
function parseSelector(selector) {
  const match = /^([a-zA-Z][\w-]*)?/.exec(selector);
  const tag = match[1] || 'div';
  const rest = selector.slice(match[0].length);
  const classes = [];
  let id = null;
  for (const part of rest.match(/[.#][\w-]+/g) ?? []) {
    if (part[0] === '.') classes.push(part.slice(1));
    else id = part.slice(1);
  }
  return { tag, id, classes };
}

function isProps(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    !(value instanceof Node) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

/** Normalises the `class` prop: string | string[] | { name: boolean }. */
export function classNames(value) {
  if (!value) return [];
  if (typeof value === 'string') return value.split(/\s+/).filter(Boolean);
  if (Array.isArray(value)) return value.flatMap(classNames);
  if (typeof value === 'object') return Object.keys(value).filter((key) => value[key]);
  return [];
}

function applyProps(el, props, isSvg) {
  let ref = null;
  for (const [key, value] of Object.entries(props)) {
    if (FORBIDDEN.has(key)) throw new Error(`h(): «${key}» no está permitido; usa nodos de texto.`);
    if (key === 'ref') {
      ref = value;
      continue;
    }
    if (key === 'class' || key === 'className') {
      const list = classNames(value);
      if (list.length) el.classList.add(...list);
      continue;
    }
    if (key === 'style') {
      if (typeof value === 'string') el.style.cssText = value;
      else if (value) {
        for (const [prop, v] of Object.entries(value)) {
          if (v === null || v === undefined || v === false) continue;
          if (prop.startsWith('--') || prop.includes('-')) el.style.setProperty(prop, String(v));
          else el.style[prop] = String(v);
        }
      }
      continue;
    }
    if (key === 'dataset') {
      for (const [k, v] of Object.entries(value ?? {})) if (v !== null && v !== undefined) el.dataset[k] = String(v);
      continue;
    }
    if (/^on[A-Z]/.test(key)) {
      if (typeof value === 'function') el.addEventListener(key.slice(2).toLowerCase(), value);
      continue;
    }
    if (value === null || value === undefined || value === false) continue;
    if (!isSvg && PROPERTIES.has(key)) {
      el[key] = value;
      continue;
    }
    el.setAttribute(key, value === true ? '' : String(value));
  }
  return ref;
}

/** Appends children: strings/numbers become text nodes; arrays are flattened; null/false are skipped. */
export function append(parent, ...children) {
  for (const child of children) {
    if (child === null || child === undefined || child === false || child === true) continue;
    if (Array.isArray(child)) append(parent, ...child);
    else if (child instanceof Node) parent.appendChild(child);
    else parent.appendChild(document.createTextNode(String(child)));
  }
  return parent;
}

/**
 * Element builder.
 *   h('button.btn.btn-primary', { type: 'button', onClick: fn, 'aria-label': 'Cerrar' }, 'Texto', iconEl)
 * Props: class (string | array | {name: bool}), style (object | string), dataset, ref (fn(el)),
 * on<Event> listeners, DOM properties (value, checked, disabled, hidden, tabIndex, ...),
 * anything else becomes an attribute (true -> empty attribute; null/undefined/false -> omitted).
 */
export function h(selector, props, ...children) {
  const { tag, id, classes } = parseSelector(selector);
  const el = document.createElement(tag);
  if (id) el.id = id;
  if (classes.length) el.classList.add(...classes);
  let ref = null;
  if (isProps(props)) ref = applyProps(el, props, false);
  else children.unshift(props);
  append(el, ...children);
  if (typeof ref === 'function') ref(el);
  return el;
}

/** SVG element builder (same prop rules as h(); every prop is an attribute). */
export function svg(tag, props, ...children) {
  const el = document.createElementNS(SVG_NS, tag);
  let ref = null;
  if (isProps(props)) ref = applyProps(el, props, true);
  else children.unshift(props);
  append(el, ...children);
  if (typeof ref === 'function') ref(el);
  return el;
}

/** DocumentFragment from children. */
export function frag(...children) {
  return append(document.createDocumentFragment(), ...children);
}

/** Removes every child. */
export function clear(el) {
  while (el.firstChild) el.removeChild(el.firstChild);
  return el;
}

/** Replaces the children of `el`. */
export function replace(el, ...children) {
  clear(el);
  return append(el, ...children);
}

export const $ = (selector, root = document) => root.querySelector(selector);
export const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));

// ---------------------------------------------------------------------------
// Match highlighting

const isDigit = (c) => c >= '0' && c <= '9';

/** Text search key of `text` (lower-case, no accents) plus the index in `text` of every key char. */
function indexText(text) {
  let norm = '';
  const map = [];
  for (let i = 0; i < text.length; i++) {
    // Non-breaking hyphens (fmt.keepHyphens) are plain hyphens for the search.
    const ch = text[i].normalize('NFD').replace(COMBINING_MARKS, '').toLowerCase().replace(NB_HYPHEN, '-');
    for (const c of ch) {
      norm += c;
      map.push(i);
    }
  }
  return { norm, map };
}

/**
 * Code search key of `text` (only [A-Z0-9], like the server's code_norm) plus the index in
 * `text` of every key char. `loose` also drops the zero padding of every digit run, like
 * code_loose ("UT-0012" -> "UT12"); runs end at separators, as on the server.
 */
function indexCode(text, loose) {
  const chars = [];
  for (let i = 0; i < text.length; i++) {
    const folded = ORDINALS.test(text[i]) ? text[i] : text[i].normalize('NFKC');
    for (const c of folded.normalize('NFD').replace(COMBINING_MARKS, '').toUpperCase()) chars.push([c, i]);
  }
  let norm = '';
  const map = [];
  let padding = false; // still in the leading zeros of a digit run
  chars.forEach(([c, i], k) => {
    if (isDigit(c) && !(k > 0 && isDigit(chars[k - 1][0]))) padding = true;
    if (loose && padding && c === '0' && k + 1 < chars.length && isDigit(chars[k + 1][0])) return;
    if (c !== '0') padding = false;
    if (/[A-Z0-9]/.test(c)) {
      norm += c;
      map.push(i);
    }
  });
  return { norm, map };
}

/** [start, end) ranges of `text` (original indexes) where each needle appears in the key. */
function findRanges({ norm, map }, needles) {
  const ranges = [];
  for (const needle of needles) {
    let from = 0;
    for (;;) {
      const at = norm.indexOf(needle, from);
      if (at < 0) break;
      ranges.push([map[at], map[at + needle.length - 1] + 1]);
      from = at + needle.length;
    }
  }
  return ranges;
}

function mergeRanges(ranges) {
  ranges.sort((a, b) => a[0] - b[0]);
  const out = [];
  for (const range of ranges) {
    const last = out[out.length - 1];
    if (last && range[0] <= last[1]) last[1] = Math.max(last[1], range[1]);
    else out.push([...range]);
  }
  return out;
}

function codeRanges(source, query) {
  const needle = codeNorm(query);
  if (!needle) return [];
  const ranges = findRanges(indexCode(source, false), [needle]);
  // "ut 12" also finds UT-0012 on the server (code_loose): mark the padded code then.
  if (!ranges.length && matchesLoose(query)) return findRanges(indexCode(source, true), [needle]);
  return ranges;
}

function textRanges(source, query) {
  const needles = textNorm(query).split(' ').filter((w) => w.length > 0);
  return needles.length ? findRanges(indexText(source), needles) : [];
}

/**
 * Returns a fragment with the parts of `text` matching `query` wrapped in <mark>.
 * mode 'code': compares only [A-Z0-9] (like the server's code_norm), so "ut12" marks "UT-12";
 *   when that finds nothing, compares without zero padding, so "ut 12" marks "UT-0012".
 * mode 'text': every word of the query, case and accent insensitive.
 * What cannot be matched is simply not marked.
 */
export function highlight(text, query, { mode = 'code' } = {}) {
  const source = String(text ?? '');
  const fragment = document.createDocumentFragment();
  const ranges = source ? (mode === 'code' ? codeRanges(source, query) : textRanges(source, query)) : [];
  let cursor = 0;
  for (const [start, end] of mergeRanges(ranges)) {
    if (start > cursor) fragment.append(source.slice(cursor, start));
    fragment.append(h('mark', source.slice(start, end)));
    cursor = end;
  }
  if (cursor < source.length) fragment.append(source.slice(cursor));
  return fragment;
}

// ---------------------------------------------------------------------------
// Trusted SVG (server generated QR code only)

const SVG_ALLOWED = new Set(['svg', 'g', 'path', 'rect', 'circle', 'line', 'polyline', 'polygon', 'defs', 'title', 'desc']);

/**
 * Parses SVG markup produced by our own server (e.g. /api/admin/server-info qrSvg)
 * into an element, dropping anything that is not plain vector geometry
 * (scripts, foreignObject, event handlers, external references).
 */
export function svgFromString(markup) {
  const doc = new DOMParser().parseFromString(String(markup ?? ''), 'image/svg+xml');
  const root = doc.documentElement;
  if (!root || root.nodeName.toLowerCase() !== 'svg' || doc.getElementsByTagName('parsererror').length) return null;
  const walk = (node) => {
    for (const child of Array.from(node.children)) {
      if (!SVG_ALLOWED.has(child.nodeName.toLowerCase())) {
        child.remove();
        continue;
      }
      walk(child);
    }
    for (const attr of Array.from(node.attributes)) {
      const name = attr.name.toLowerCase();
      if (name.startsWith('on') || name === 'href' || name === 'xlink:href' || name === 'style') {
        node.removeAttribute(attr.name);
      }
    }
  };
  walk(root);
  return document.importNode(root, true);
}
